package codegen

// mockTemplate is an inline template for proto service mock generation.
// Kept separate from the embedded FS templates because proto mocks need
// Connect-specific types and method signatures.
const mockTemplate = `// Code generated by forge. DO NOT EDIT.
// forge-owned: regenerated every run — do not edit (forge project disown to take ownership)
// Source: proto service {{.ProtoServiceName}} — one recording mock per rpc it declares.
package mocks

import (
{{- if .HasMethods}}
	"context"
{{- end}}
	"net/http"

	"connectrpc.com/connect"
{{- if .HasMethods}}
	"github.com/reliant-labs/forge/pkg/svcerr"
{{- end}}
{{- if .NeedsPb}}
	pb "{{.GoPackage}}"
{{- end}}
{{- range .ForeignImports}}
	{{.Alias}} "{{.Path}}"
{{- end}}
	"{{.GoPackage}}/{{.PkgName}}connect"
{{- if .NeedsEmptypb}}
	"google.golang.org/protobuf/types/known/emptypb"
{{- end}}
)

// {{.ServiceName}}Mock is a mock implementation for testing
type {{.ServiceName}}Mock struct {
	{{.PkgName}}connect.Unimplemented{{.ServiceName}}Handler

	// Function fields for each RPC method
{{range .Methods}}	{{.Name}}Func func({{.Signature}}) {{.ReturnType}}
{{end}}
}

{{- if not .HasRegisterRPC}}
// Register implements forge.Service
func (m *{{.ServiceName}}Mock) Register(mux *http.ServeMux, opts ...connect.HandlerOption) {
	path, handler := {{.PkgName}}connect.New{{.ServiceName}}Handler(m, opts...)
	mux.Handle(path, handler)
}
{{- else}}
// Mount registers this mock's Connect routes on mux.
//
// NOT named Register: this service declares an RPC called Register, and the
// mount helper and the RPC method cannot share one name on one type. The RPC
// wins, because it is the service's own API — mountkit.Service is satisfied
// by a small adapter instead, which is the cheaper of the two collisions.
func (m *{{.ServiceName}}Mock) Mount(mux *http.ServeMux, opts ...connect.HandlerOption) {
	path, handler := {{.PkgName}}connect.New{{.ServiceName}}Handler(m, opts...)
	mux.Handle(path, handler)
}
{{- end}}

// Name implements forge.Service
func (m *{{.ServiceName}}Mock) Name() string {
	return "{{.ServiceName}}Mock"
}

{{range .Methods}}
// {{.Name}} delegates to {{.Name}}Func if set
func (m *{{$.ServiceName}}Mock) {{.Name}}({{.Signature}}) {{.ReturnType}} {
	if m.{{.Name}}Func != nil {
		return m.{{.Name}}Func({{.CallArgs}})
	}
	return {{.ReturnStub}}
}
{{end}}
`
